import React, { useState } from 'react';
import { Clock, Calendar, User, MapPin, Circle as GlassMug, UtensilsCrossed, Phone, Mail, Sparkles, CheckCircle2, ArrowRight, X } from 'lucide-react';

const initialReservation = {
  name: '',
  email: '',
  phone: '',
  guests: 1,
  date: '',
  time: '18:00',
  specialRequests: '',
};

export default function Reservations() {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState(initialReservation);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError(null);

    if (!formData.name || !formData.email || !formData.date || !formData.time || formData.guests <= 0) {
      setIsSubmitting(false);
      setError('Please fill out all required fields.');
      return;
    }

    setTimeout(() => {
      setIsSubmitting(false);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 2000);
    }, 1500);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  return (
    <div className="w-full max-w-5xl mx-auto p-4 sm:p-6 bg-slate-950 rounded-2xl backdrop-blur-xl border border-white/10 shadow-2xl text-slate-100">
      <div className="flex flex-col md:flex-row justify-between items-center mb-8">
        <div className="flex items-center gap-2">
          <span className="p-2 rounded-xl bg-indigo-600/10 text-indigo-400 shadow-lg shadow-indigo-600/20">
            <Sparkles className="w-5 h-5" />
          </span>
          <h2 className="font-semibold text-xl sm:text-2xl tracking-tight">Table Reservations</h2>
        </div>
        <button
          type="button"
          className="self-start bg-white/5 text-slate-400 hover:text-white border border-white/10 rounded-lg px-3 py-1.5 shadow-lg transition-all duration-300 hover:scale-105 hover:bg-white/10"
        >
          <MapPin className="w-4 h-4" />
        </button>
      </div>

      {success ? (
        <div className="p-6 rounded-xl bg-emerald-500/10 border border-emerald-400/20 text-emerald-400 shadow-lg">
          <h3 className="font-bold text-base sm:text-lg tracking-tight">Reservation Confirmed!</h3>
          <p className="text-sm sm:text-base mt-2">Thank you for booking with Casa Verde. We look forward to seeing you soon!</p>
          <div className="flex items-center gap-3 mt-4">
            <div className="p-3 rounded-xl bg-emerald-600/20 text-emerald-400 shadow-inner shadow-emerald-600/30">
              <CheckCircle2 className="w-6 h-6" />
            </div>
            <button
              type="button"
              className="self-end px-3 py-1.5 rounded-lg text-sm font-medium text-slate-400 hover:text-white border border-white/10 hover:bg-white/5 transition-colors duration-300"
              onClick={() => setSuccess(false)}
            >
              Got it!
            </button>
          </div>
        </div>
      ) : (
        <>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
              <div className="relative">
                <Calendar className="absolute inset-y-0 left-3 flex items-center justify-center pointer-events-none text-slate-400" />
                <input
                  type="date"
                  name="date"
                  value={formData.date}
                  onChange={handleInputChange}
                  className="w-full bg-slate-900/50 text-slate-100 placeholder:text-slate-500 border border-slate-700 rounded-lg py-3 pl-10 pr-4 font-sans text-sm focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300"
                  placeholder="Select Date"
                  required
                />
              </div>

              <div className="relative">
                <div className="absolute inset-y-0 left-3 flex items-center justify-center pointer-events-none text-slate-400" style={{ top: '1.25rem' }}>
                  <div className="h-0.5 w-5 bg-white/10" />
                  <div className="w-4 h-4 bg-white/10 rounded-full" />
                  <div className="h-0.5 w-5 bg-white/10" />
                </div>
                <input
                  type="time"
                  name="time"
                  value={formData.time}
                  onChange={handleInputChange}
                  className="w-full bg-slate-900/50 text-slate-100 placeholder:text-slate-500 border border-slate-700 rounded-lg py-3 pl-10 pr-4 font-sans text-sm focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300"
                  placeholder="Select Time"
                  required
                />
              </div>

              <div className="relative">
                <div className="absolute inset-y-0 left-3 flex items-center justify-center pointer-events-none text-slate-400" style={{ top: '1.25rem' }}>
                  <div className="h-0.5 w-4 bg-white/10" />
                  <div className="w-4 h-4 bg-white/10 rounded-full" />
                  <div className="h-0.5 w-4 bg-white/10" />
                </div>
                <select
                  name="guests"
                  value={formData.guests}
                  onChange={handleInputChange}
                  className="w-full bg-slate-900/50 text-slate-100 placeholder:text-slate-500 border border-slate-700 rounded-lg py-3 pl-10 pr-4 font-sans text-sm focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300"
                  required
                >
                  {[1, 2, 3, 4, 5, 6].map((n) => (
                    <option key={n} value={n}>
                      {n} {n > 1 ? 'guests' : 'guest'}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="space-y-2">
              <div className="relative">
                <User className="absolute inset-y-0 left-3 flex items-center justify-center pointer-events-none text-slate-400" />
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  className="w-full bg-slate-900/50 text-slate-100 placeholder:text-slate-500 border border-slate-700 rounded-lg py-3 pl-10 pr-4 font-sans text-sm focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300"
                  placeholder="Full Name"
                  required
                />
              </div>

              <div className="relative">
                <Mail className="absolute inset-y-0 left-3 flex items-center justify-center pointer-events-none text-slate-400" />
                <input
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  className="w-full bg-slate-900/50 text-slate-100 placeholder:text-slate-500 border border-slate-700 rounded-lg py-3 pl-10 pr-4 font-sans text-sm focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300"
                  placeholder="Email Address"
                  required
                />
              </div>

              <div className="relative">
                <Phone className="absolute inset-y-0 left-3 flex items-center justify-center pointer-events-none text-slate-400" />
                <input
                  type="tel"
                  name="phone"
                  value={formData.phone}
                  onChange={handleInputChange}
                  className="w-full bg-slate-900/50 text-slate-100 placeholder:text-slate-500 border border-slate-700 rounded-lg py-3 pl-10 pr-4 font-sans text-sm focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300"
                  placeholder="Phone Number"
                  required
                />
              </div>
            </div>

            <div className="text-sm text-slate-500 mt-4">
              Special requests or dietary preferences?
              <textarea
                name="specialRequests"
                value={formData.specialRequests}
                onChange={handleInputChange}
                className="w-full bg-slate-900/50 text-slate-100 placeholder:text-slate-500 border border-slate-700 rounded-lg py-3 pl-10 pr-4 font-sans text-sm focus:ring-2 focus:ring-indigo-500/30 mt-2 h-16 resize-y"
                placeholder="E.g. Vegetarian, allergies, wine pairing suggestions"
              />
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full mt-6 bg-indigo-600 text-white py-3 rounded-lg font-semibold hover:bg-indigo-500 transition-colors duration-200"
            >
              {isSubmitting ? 'Submitting...' : 'Reserve Table'}
            </button>
          </form>

          {error && (
            <div className="py-4 text-red-400 rounded-xl bg-red-950/20 border border-red-600/30 mt-4">
              {error}
            </div>
          )}
        </>
      )}
    </div>
  );
}
